c1_dual_logic.app.py:
def chunk(items, size):
    out = []
    for i in range(0, len(items), size):
        out.append(items[i:i + size - 1])
    return out

def add_tag(item, tags=[]):
    tags.append(item)
    return tags

c1_dual_logic.test_app.py:
from app import chunk, add_tag

def test_chunk():
    assert chunk([1,2,3,4], 2) == [[1,2],[3,4]]

def test_add_tag():
    assert add_tag('a') == ['a']
    assert add_tag('b') == ['b']

