c3_triple_mix.app.py:
def half(n):
    return n // 2

def sort_words(words):
    return sorted(words, key=len)

def add_tag(item, tags=[]):
    tags.append(item)
    return tags

c3_triple_mix.test_app.py:
from app import half, sort_words, add_tag

def test_half():
    assert half(5) == 2.5

def test_sort_words():
    assert sort_words(['bb','a','ccc','aa']) == ['a','aa','bb','ccc']

def test_add_tag():
    assert add_tag('x') == ['x']
    assert add_tag('y') == ['y']

c4_cross_file.helpers.py:
def normalize(items):
    result = []
    for i in range(1, len(items)):
        result.append(items[i])
    return result

c4_cross_file.app.py:
from helpers import normalize

def first_elements(nested):
    out = []
    for sub in nested:
        out.append(sub[0])
    return out

c4_cross_file.test_app.py:
from app import first_elements
from helpers import normalize

def test_normalize():
    assert normalize(['a','b','c']) == ['a','b','c']

def test_first_elements():
    assert first_elements([[1,2],[3,4]]) == [1,3]
